shared_html.shared_css:
/* ============================================================
   Shared nav + footer — Atelier Vesperia
   Roman Imperial · modern variant
   ============================================================ */

.site-nav,
.site-footer {
  font-family: "Inter", system-ui, sans-serif;
  color: var(--text);
  background: var(--bg);
}

/* ---------- Meander (Greek key) strip generated in CSS ---------- */
.site-nav__meander,
.site-footer__meander {
  height: 14px;
  background-color: var(--ornament);
  -webkit-mask-image: url("svg/meander-greek-key.svg");
          mask-image: url("svg/meander-greek-key.svg");
  -webkit-mask-repeat: repeat-x;
          mask-repeat: repeat-x;
  -webkit-mask-size: auto 14px;
          mask-size: auto 14px;
  opacity: 0.92;
}

/* ---------- HEADER ---------- */
.site-nav {
  border-bottom: 1px solid rgba(26, 26, 26, 0.12);
}

.site-nav__rule {
  height: 6px;
  background: var(--accent);
}

.site-nav__inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 2.25rem 2rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.25rem;
  text-align: center;
}

.site-nav__wordmark {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  text-decoration: none;
  color: var(--primary);
}

.site-nav__kicker {
  font-size: 0.7rem;
  letter-spacing: 0.36em;
  color: var(--text-emphasis);
  font-weight: 500;
}

.site-nav__name {
  font-family: "Marcellus", serif;
  font-size: clamp(1.6rem, 2.8vw, 2.4rem);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  line-height: 1;
}

.site-nav__sub {
  font-style: italic;
  font-size: 0.9rem;
  color: var(--primary);
  opacity: 0.7;
  letter-spacing: 0.04em;
}

.site-nav__links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 0.5rem 0.9rem;
  padding-top: 0.5rem;
  border-top: 1px solid rgba(26, 26, 26, 0.15);
  margin-top: 0.5rem;
}

.site-nav__links a {
  font-family: "Marcellus", serif;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  font-size: 0.78rem;
  color: var(--primary);
  text-decoration: none;
  padding: 0.25rem 0.1rem;
  border-bottom: 1px solid transparent;
  transition: color .2s, border-color .2s;
}

.site-nav__links a:hover,
.site-nav__links a:focus {
  color: var(--accent);
  border-bottom-color: var(--secondary);
  outline: none;
}

.site-nav__sep {
  color: var(--secondary);
  font-size: 0.9rem;
}

@media (min-width: 880px) {
  .site-nav__inner {
    grid-template-columns: auto 1fr;
    text-align: left;
    align-items: end;
    gap: 2rem;
  }
  .site-nav__wordmark { align-items: flex-start; }
  .site-nav__links {
    justify-content: flex-end;
    border-top: none;
    margin-top: 0;
    padding-top: 0;
  }
}

/* ---------- FOOTER ---------- */
.site-footer {
  margin-top: 4rem;
  border-top: 1px solid rgba(26, 26, 26, 0.12);
}

.site-footer__inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 2.5rem 2rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 720px) {
  .site-footer__inner {
    grid-template-columns: 1.3fr 1fr 1fr 1fr;
    gap: 2.5rem;
  }
}

.site-footer__col h4 {
  font-family: "Marcellus", serif;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  font-size: 0.78rem;
  color: var(--text-emphasis);
  margin: 0 0 0.75rem;
  padding-bottom: 0.4rem;
  border-bottom: 1px solid var(--secondary);
}

.site-footer__col p {
  margin: 0 0 0.75rem;
  font-size: 0.92rem;
  line-height: 1.6;
  color: var(--primary);
}

.site-footer__col--mark {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.site-footer__name {
  font-family: "Marcellus", serif;
  font-size: 1.6rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--primary);
}

.site-footer__tag {
  font-size: 0.72rem;
  letter-spacing: 0.32em;
  color: var(--accent);
  text-transform: uppercase;
}

.site-footer__nav {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.site-footer__nav a {
  font-family: "Inter", sans-serif;
  font-size: 0.9rem;
  color: var(--primary);
  text-decoration: none;
  letter-spacing: 0.04em;
  border-bottom: 1px solid transparent;
  width: max-content;
  transition: color .2s, border-color .2s;
}

.site-footer__nav a:hover,
.site-footer__nav a:focus {
  color: var(--accent);
  border-bottom-color: var(--accent);
  outline: none;
}

.site-footer__rule {
  height: 1px;
  background: var(--ornament);
  opacity: 0.25;
  margin: 0 2rem;
}

.site-footer__colophon {
  max-width: 1180px;
  margin: 0 auto;
  padding: 1rem 2rem 2rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 0.75rem 1.25rem;
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--primary);
  opacity: 0.8;
  text-align: center;
}

.site-footer__dot {
  color: var(--secondary);
  font-size: 1rem;
  letter-spacing: 0;
}
